import{_ as t,o,c as n,a2 as a}from"./chunks/framework.Dhf_H6O0.js";const u=JSON.parse('{"title":"Open WebUI Integration","description":"","frontmatter":{},"headers":[],"relativePath":"connecting-tools/open-webui.md","filePath":"connecting-tools/open-webui.md"}'),r={name:"connecting-tools/open-webui.md"};function s(i,e,l,c,h,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="open-webui-integration" tabindex="-1">Open WebUI Integration <a class="header-anchor" href="#open-webui-integration" aria-label="Permalink to &quot;Open WebUI Integration&quot;">​</a></h1><p>Open WebUI is a popular self-hosted AI chat interface. This guide shows you how to connect it to your MCPBehindIT servers.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>MCPBehindIT gateway is <strong>running</strong> (green status badge)</li><li>At least one server is <strong>enabled</strong> (check the Servers page)</li><li>Open WebUI is installed and accessible</li></ul><h2 id="step-by-step" tabindex="-1">Step by step <a class="header-anchor" href="#step-by-step" aria-label="Permalink to &quot;Step by step&quot;">​</a></h2><ol><li>In MCPBehindIT, go to <strong>Home</strong> → <strong>Clients</strong> tab.</li><li>Find the server you want to connect (e.g., <code>telecontext</code>).</li><li>Click <strong>Copy OpenAPI</strong> to copy the spec URL to your clipboard.</li><li>Open <strong>Open WebUI</strong> in your browser.</li><li>Go to <strong>Admin</strong> → <strong>Settings</strong> → look for <strong>External tools</strong> or <strong>OpenAPI</strong> (exact label depends on your Open WebUI version).</li><li>Click <strong>Add tool</strong> (or equivalent).</li><li>Paste the <strong>OpenAPI URL</strong> from your clipboard.</li><li>Save.</li><li>Start a new chat in Open WebUI. The tools from your MCP server should now be available.</li></ol><div class="tip custom-block"><p class="custom-block-title">Built-in instructions</p><p>MCPBehindIT includes these steps directly in the app. On the <strong>Clients</strong> tab, expand the <strong>Open WebUI</strong> section for the same walkthrough. You can click <strong>Copy these steps</strong> to save them.</p></div><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><h3 id="use-localhost-not-127-0-0-1" tabindex="-1">Use localhost, not 127.0.0.1 <a class="header-anchor" href="#use-localhost-not-127-0-0-1" aria-label="Permalink to &quot;Use localhost, not 127.0.0.1&quot;">​</a></h3><p>If both MCPBehindIT and Open WebUI run on the same Mac, use <code>http://localhost:8000/...</code> rather than <code>http://127.0.0.1:8000/...</code>. Some browsers treat <code>127.0.0.1</code> differently for CORS, which can cause issues.</p><h3 id="multiple-servers" tabindex="-1">Multiple servers <a class="header-anchor" href="#multiple-servers" aria-label="Permalink to &quot;Multiple servers&quot;">​</a></h3><p>Add one tool per server. Each server has its own OpenAPI URL. If you have three servers (telecontext, local-rag, memory), add three tool entries in Open WebUI.</p><h3 id="tools-not-appearing" tabindex="-1">Tools not appearing? <a class="header-anchor" href="#tools-not-appearing" aria-label="Permalink to &quot;Tools not appearing?&quot;">​</a></h3><ul><li>Confirm the gateway is running (check the Dashboard).</li><li>Confirm the server is enabled (check the Servers page).</li><li>Check that the server name in the URL matches what&#39;s in Open WebUI.</li><li>Look at <a href="./../using-the-app/logs.html">Logs</a> for connection errors.</li></ul><h3 id="open-webui-in-docker" tabindex="-1">Open WebUI in Docker <a class="header-anchor" href="#open-webui-in-docker" aria-label="Permalink to &quot;Open WebUI in Docker&quot;">​</a></h3><p>If Open WebUI runs inside Docker on the same Mac, it can access the gateway at <code>http://host.docker.internal:8000/...</code> instead of <code>localhost</code>.</p>',16)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
